    private fun clips(): List<TimelineClip> =
        AlightXmlImporter.parse(graph, 1920f).snapshot.tracks.flatMap { it.clips }

    // ---- G1: the bars' wipe masks carry the data heights ------------------------------------

    /** Visible fraction of a wipe state along the layer's vertical axis (the states here are
     *  turned 90°, so the band is the state's width about its centre). */
    private fun visFrac(m: com.example.model.ClipMask, relMs: Long): Float {
        val s = m.stateAt(relMs)
        return (minOf(1f, s.cy + s.w / 2) - maxOf(0f, s.cy - s.w / 2)).coerceAtLeast(0f)
    }

    @Test
    fun barWipesSettleAtTheAlightHeights() {
        val bars = clips().filter { it.type == LayerType.SHAPE && it.masks.isNotEmpty() }
        assertEquals(28, bars.size)   // 7 bars x the four embedded copies of the bar set
        val settled = bars.map { visFrac(it.masks[0], 3000L) }
        // Alight's settled frame, bottom-up fractions of the grid (frame evidence, findings doc):
        for (e in listOf(0.279f, 0.556f, 0.356f, 0.627f, 0.934f, 0.515f, 0.772f)) {
            assertEquals("settled fraction $e x4", 4, settled.count { abs(it - e) < 0.01f })
        }
        // Bar "1" opens from nothing: closed at its first key, settled window centred low.
        val bar1 = bars.first { it.name == "1" }
        assertEquals(0f, visFrac(bar1.masks[0], 0L), 1e-6f)
        val st = bar1.masks[0].stateAt(3000L)
        assertEquals(0.8605f, st.cy, 0.01f)
        assertEquals(90f, st.rot, 0.01f)
    }

    // ---- G1 render side: the own-mask remap (OverlayMasks) ---------------------------------

    @Test
    fun overlayMaskRemapMovesTheWindowWithTheBox() {
        // A wipe state in a layer's own box (fractions of the box): centre (0.5, 0.8605), size
        // (0.5, 2.5) — Graph bar 1 settled. The box sits at (1000, 600), 200x400, in a 1920x1080 frame.
        val arr = FloatArray(ClipMaskLibrary.STRIDE)
        arr[0] = 0f      // RECT
        arr[3] = 0.5f; arr[4] = 0.8605f; arr[5] = 0.5f; arr[6] = 2.5f
        arr[10] = 80f    // opacity: not geometry, carried raw
        val out = OverlayMasks.remap(arr, OverlayMasks.Box(1000f, 600f, 200f, 400f, 0f, false, false), 0f, 0f, 1920f, 1080f)
        assertEquals(1000f / 1920f, out[3], 1e-4f)
        assertEquals((600f + 0.3605f * 400f) / 1080f, out[4], 1e-4f)
        assertEquals(0.5f * 200f / 1920f, out[5], 1e-5f)
        assertEquals(2.5f * 400f / 1080f, out[6], 1e-4f)
        assertEquals(80f, out[10], 1e-6f)
    }

    @Test
    fun overlayMaskRemapRotatesWithTheLayer() {
        val arr = FloatArray(ClipMaskLibrary.STRIDE)
        arr[3] = 0.25f; arr[4] = 0.5f; arr[5] = 0.1f; arr[6] = 0.1f
        val out = OverlayMasks.remap(arr, OverlayMasks.Box(500f, 500f, 100f, 100f, 90f, false, false), 0f, 0f, 1000f, 1000f)
        // The centre offset (-25, 0) in the box turns to (0, -25) under the layer's 90° clockwise turn.
        assertEquals(0.5f, out[3], 1e-4f)
        assertEquals(0.475f, out[4], 1e-4f)
        assertEquals(90f, out[7], 1e-3f)
    }

    @Test
    fun overlayMaskRemapIntoAnFxRegionIsIdentityWhenTheRegionIsTheBox() {
        val arr = FloatArray(ClipMaskLibrary.STRIDE)
        arr[3] = 0.5f; arr[4] = 0.5f; arr[5] = 1f; arr[6] = 1f; arr[8] = 10f
        val out = OverlayMasks.remap(arr, OverlayMasks.Box(960f, 540f, 400f, 300f, 0f, false, false), 760f, 390f, 400f, 300f)
        assertEquals(0.5f, out[3], 1e-4f)
        assertEquals(0.5f, out[4], 1e-4f)
        assertEquals(1f, out[5], 1e-4f)
        assertEquals(1f, out[6], 1e-4f)
        assertEquals(10f, out[8], 1e-3f)   // feather keeps its pixel width (box height == target height)
    }

    // ---- G2: the counter rides its keyframes' easing ----------------------------------------

    @Test
    fun counterFollowsTheEasedCurve() {
        val counter = clips().single { c -> c.textAnimators.any { it.effectId == AlightXmlImporter.COUNTER } }
        // The offset keys arrive WITH their easing (the fix: AnimKey keeps it, TextAnimEval applies it).
        val keys = counter.textAnimators.single { it.effectId == AlightXmlImporter.COUNTER }.props.getValue("offset").keys
        assertEquals(2, keys.size)
        assertTrue(keys[1].easing != null)
        assertEquals("0", CounterEval.displayText(counter.text ?: "0", counter, counter.startMs))
        assertEquals("11", CounterEval.displayText(counter.text ?: "0", counter, counter.startMs + 1000))   // linear: "6"
        assertEquals("12", CounterEval.displayText(counter.text ?: "0", counter, counter.startMs + 1500))   // linear: "9"
        assertEquals("12", CounterEval.displayText(counter.text ?: "0", counter, counter.startMs + 2000))
    }

    // ---- G3: nested-scene sizes convert against the root canvas ------------------------------

    @Test
    fun cardDrawsAtItsXmlSize() {
        val card = clips().filter { it.name == "Rounded Rectangle 1" }.maxByOrNull { it.shapeDrawScaleX }!!
        // The shape box at the ROOT canvas: 1920 * 130/360 = 693.33 px. The card is 1211 px wide
        // in Alight (569 * 2 * 1.064148, XML numbers); converting against its own 2005-wide scene
        // drew it 1159.6 px wide and pushed the scene's content off the card's edges.
        assertEquals(1211.0f, card.shapeDrawScaleX * (1920f * 130f / 360f), 2.0f)
    }

    @Test
    fun counterScaleUsesTheRootCanvasToo() {
        val counter = clips().single { c -> c.textAnimators.any { it.effectId == AlightXmlImporter.COUNTER } }
        // scalePct = size 48 x scale 1.267782 x ownW 2005 / 640, against the app font base
        // (0.11 x rootW 1920): 90.27 — the drawn em is AM's 190.6 px. Converting the base
        // against the text's OWN scene instead gave 86.44 (the em drawn 4.2 % small).
        assertEquals(90.27f, counter.scalePercent, 0.6f)
    }

    // ---- G4: repeat offsets live in the layer's own scene ------------------------------------

    @Test
    fun verticalLinesCopiesStayInsideTheCard() {
        val all = clips()
        val rig = ParentRig(all) { c, t -> c.renderAt(t) }
        val vl = all.single { it.name == "Vertical Lines" }
        val local = vl.renderAt(2000)
        val adj = rig.adjusted(vl, 2000)
        val (os, orot) = RepeatEval.outerOf(local, adj)
        assertEquals(0.74668f, os, 0.01f)   // Group 1's keyframed scale at t = 2000 (XML numbers)
        val copies = RepeatEval.copiesOf(adj, timeMs = 2000, outerScale = os, outerRotDeg = orot)
        assertEquals(8, copies.size)
        val xs = copies.map { 960f + it.transformX }   // stored units are root px (previewW = 1920)
        assertEquals(109.0f, xs[1] - xs[0], 1.5f)      // 146 in the Lines scene, x 0.74668 outside it
        for (x in xs) assertTrue("copy at $x inside the card", x in 500f..1415f)   // card: 506.6..1411.0
        // The pre-fix behaviour, for the record: without the ancestor similarity the copies step
        // the full 146 and the last two march out of the card (the stray lines of the recording).
        val naive = RepeatEval.copiesOf(adj, timeMs = 2000)
        assertTrue(960f + naive.last().transformX > 1500f)
    }
